const todayLogic = `
renderVals() {
  ${T}${DB_JS}
  ${TODAY_ASSIGN_JS(false)}
  const td = db.today();
  ${FORECAST_JS('td.forecast', 64)}
  const streak = 'linear-gradient(135deg, #FFC857 0%, #F58A3A 55%, #EE5A36 100%)';
  const plural = (n, w) => n + ' ' + w + (n === 1 ? '' : 's');
  // Most urgent first: overdue cards, then cards due today, then whatever is due soonest.
  // All caught up: nothing due today, so every deck shows when it's next due.
  const caught = !td.due;
  const decks = db.decks().filter(d => !d.paused).sort((a, b) => (b.overdue - a.overdue) || (b.due - a.due) || ((a.soon ?? 1e9) - (b.soon ?? 1e9))).map(d => {
    const tag = d.overdue ? { tag: d.overdue + ' overdue', tagBg: t.againTint, tagFg: t.again }
      : d.due ? { tag: 'Due today', tagBg: t.hardTint, tagFg: t.hard }
      : d.soon == null ? { tag: d.fresh ? d.fresh + ' new' : 'No cards yet', tagBg: t.surf, tagFg: t.muted }
      : { tag: d.soon === 1 ? 'Next: tomorrow' : 'Next: in ' + d.soon + ' days', tagBg: t.surf, tagFg: t.muted };
    // Flashcards whenever there's something to study (cards due, or new ones to learn).
    // A deck with an exam coming says so (the owner's note: "Exam in 12 days · 84 cards to review first").
    return { ...d, ...tag, canStudy: d.due > 0 || d.fresh > 0, noStudy: !d.due && !d.fresh, countColor: d.due ? t.text : t.muted, hasExam: !!d.exam, examLine: d.exam ? d.exam.line : '' };
  });
  return {
    ${MESH_VALS('Iris')}
    t, decks, ...chrome,
    heroMeta: td.date + (td.streak ? ' · ' + td.streak + '-day streak' : ''),
    streakTitle: td.streak ? td.streak + '-day streak' : 'No streak yet', bestLine: 'Best: ' + plural(td.best, 'day'),
    heroTitle: caught ? 'All caught up' : plural(td.due, 'card') + ' due',
    heroSub: caught ? (td.next ? 'Next review ' + td.next.day + ' · ' + plural(td.next.n, 'card') : 'Nothing scheduled yet') : 'About ' + plural(td.minutes, 'minute'),
    // Only Learn mode's button says Learn (the owner: "learn button needs to be 'learn'"); this one starts flashcards.
    heroCta: caught ? (td.fresh ? 'Study ' + plural(td.fresh, 'new card') : 'Add cards') : 'Study all',
    heroHref: caught && !td.fresh ? td.newCardHref : td.studyHref, newCardHref: td.newCardHref,
    week: td.week.map(w => ({ d: w.d, done: w.done, fill: w.done ? streak : t.surf2, ring: w.today ? '0 0 0 2px ' + t.surf + ', 0 0 0 4px #F58A3A' : 'none', labelColor: w.today ? t.text : t.muted, weight: w.today ? '600' : '400' })),
    forecast, dueTotal, busy, assignments: assignRows, hasAssignments: assignRows.length > 0
  };
}`;

// Decks
// Tags: each has a color. Decks are tagged; filter by tag on Decks, edit tags in New deck and Deck settings.
const TAG_JS = `const tagC = { Biology: '#30A46C', Chemistry: '#F76B15', Languages: '#3E63DD', MCAT: '#8E4EC6', History: '#AD7F58', 'Computer science': '#12A594', Exam: '#E5484D', 'Year 1': '#0090FF',
    Energy: '#D6409F', Organelles: '#12A594', 'Exam 1': '#E5484D', 'Exam 2': '#F76B15', Diagrams: '#3E63DD', Proteins: '#8E4EC6', Pronunciation: '#0090FF', Cells: '#3E63DD',
    'BIO 201': '#05A2C2', 'Fall 2026': '#AD7F58', Midterm: '#F76B15', 'Final exam': '#E5484D', 'Pre-med': '#E93D82', Lab: '#12A594', 'Must know': '#AB4ABA', Mitochondria: '#30A46C', Tricky: '#F76B15' };
  const tagPal = ['#30A46C', '#F76B15', '#3E63DD', '#8E4EC6', '#AD7F58', '#12A594', '#E5484D', '#0090FF', '#D6409F', '#05A2C2'];
  const tagCol = g => tagC[g] || tagPal[Array.from(g).reduce((a, ch) => a + ch.charCodeAt(0), 0) % tagPal.length];
  const tagChip = g => ({ label: g, dot: tagCol(g), bg: tagCol(g) + '26', fg: tagCol(g) });
  // More tags than room: show the first few, then a +N chip in the last slot (so never "+1").
  const tagFit = (tags, max) => { const tg = tags || [], vis = tg.length > max ? tg.slice(0, max - 1) : tg; return { vis, more: tg.length - vis.length }; };
  // Add tag: find any tag you have, tick it on or off, or make a new one.
  const tagPicker = (cur, set, key, own) => {
    const st = this.state, open = st[key + 'Open'] == null ? !!this.props.tagPicker : st[key + 'Open'];
    const q = (st[key + 'Q'] || '').trim(), ql = q.toLowerCase();
    const lib = Array.from(new Set([...(own || Object.keys(tagC)), ...cur])).sort((a, b) => a.localeCompare(b));
    const shown = lib.filter(g => !ql || g.toLowerCase().includes(ql));
    return {
      open, expanded: open ? 'true' : 'false', query: q, count: String(cur.length),
      toggle: () => this.setState({ [key + 'Open']: !open, [key + 'Q']: '' }), close: () => this.setState({ [key + 'Open']: false, [key + 'Q']: '' }),
      setQuery: e => this.setState({ [key + 'Q']: e && e.target ? e.target.value : '' }),
      options: shown.map(g => ({ ...tagChip(g), on: cur.includes(g), pressed: cur.includes(g) ? 'true' : 'false', pick: () => set(cur.includes(g) ? cur.filter(x => x !== g) : [...cur, g]) })),
      canMake: !!q && !lib.some(g => g.toLowerCase() === ql), makeLabel: 'Make “' + q + '”',
      make: () => { set([...cur, q]); this.setState({ [key + 'Q']: '' }); }
    };
  };`;
// Tag menus: a search box, then one row per tag (color dot, name, optional count, a check when it's on).
const tagSearch = (q, set, ph, h = 40) => `<label style="display: flex; align-items: center; gap: 8px; height: ${h}px; flex-shrink: 0; padding: 0 14px; box-sizing: border-box; border-radius: 999px; background: {{t.surf}}; color: {{t.muted}};">${svg(I.search, 14)}<span style="position: absolute; left: -9999px;">${ph}</span><input value="{{${q}}}" onChange="{{${set}}}" placeholder="${ph}" style="flex-grow: 1; min-width: 0; border: 0; outline: 0; background: transparent; font: inherit; font-size: ${h > 40 ? 16 : 14}px; color: {{t.text}};"></label>`;
const tagRow = (o, { count = false, h = 38, line = false } = {}) => `<button type="button" onClick="{{${o}.pick}}" aria-pressed="{{${o}.pressed}}" style="height: ${h}px; flex-shrink: 0; padding: 0 ${line ? 4 : 12}px; display: flex; align-items: center; gap: 10px; border: 0; border-radius: ${line ? 0 : 12}px; ${line ? 'border-bottom: 1px solid {{t.line}}; ' : ''}background: transparent; color: {{t.text}}; font: inherit; font-size: ${h > 40 ? 16 : 14}px; text-align: left; cursor: pointer;"><span style="width: ${h > 40 ? 10 : 8}px; height: ${h > 40 ? 10 : 8}px; flex-shrink: 0; border-radius: 5px; background: {{${o}.dot}};"></span><span style="flex-grow: 1; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">{{${o}.label}}</span>${count ? `<span style="font-family: ${MONO}; font-size: 12px; color: {{t.muted}};">{{${o}.count}}</span>` : ''}<sc-if value="{{${o}.on}}" hint-placeholder-val="{{ false }}"><span style="display: flex;">${svg(I.check, 15, 2.4)}</span></sc-if></button>`;
const popBox = 'box-sizing: border-box; padding: 8px; border-radius: 22px; background: {{t.bg}}; color: {{t.text}}; box-shadow: 0 18px 48px rgba(0,0,0,.2), 0 0 0 1px {{t.line}}; display: flex; flex-direction: column; gap: 4px;';
// Menus and popovers carry data-sc-pop, next to the button that opens them (aria-expanded). In the app (web/app.js),
// Escape or a click outside closes one by pressing that button, and one that would run off the bottom of the window (or
// of what scrolls it) opens above its button instead, or moves up to fit.
// Filter by tag: every tag, with how many decks (or cards) have it.
const tagMenu = (m, pos, { label = 'Filter by tag', find = 'Find a tag', none = 'No tags match' } = {}) => `<sc-if value="{{${m}.open}}" hint-placeholder-val="{{ false }}"><div role="dialog" aria-label="${label}" data-sc-pop style="position: absolute; ${pos} z-index: 30; width: 300px; ${popBox}">${tagSearch(m + '.query', m + '.setQuery', find)}<div style="max-height: 304px; overflow-y: auto; scrollbar-width: thin; display: flex; flex-direction: column;"><sc-for list="{{${m}.rows}}" as="o" hint-placeholder-count="6">${tagRow('o', { count: true })}</sc-for><sc-if value="{{${m}.none}}" hint-placeholder-val="{{ false }}"><span style="padding: 10px 12px; font-size: 13px; color: {{t.muted}};">${none}</span></sc-if></div></div></sc-if>`;
const makeRow = (pk, h = 38) => `<sc-if value="{{${pk}.canMake}}" hint-placeholder-val="{{ false }}"><button type="button" onClick="{{${pk}.make}}" style="height: ${h}px; flex-shrink: 0; padding: 0 12px; display: flex; align-items: center; gap: 10px; border: 0; border-radius: 12px; background: {{t.surf}}; color: {{t.text}}; font: inherit; font-size: ${h > 40 ? 16 : 14}px; font-weight: 600; text-align: left; cursor: pointer;">${svg(I.plus, 13, 2.4)}{{${pk}.makeLabel}}</button></sc-if>`;
// Tags on a deck or card: x removes one. Add tag opens the picker: a menu on web (always 320 wide, above the tags with
// `up`; in the card editor it used to shrink to the Add tag button's width), its own sheet on iPhone.
const TAG_EDIT = (list, pk, phone = false, up = false) => `<div style="${phone ? '' : 'position: relative; '}display: flex; flex-wrap: wrap; gap: 6px;"><sc-for list="{{${list}}}" as="g" hint-placeholder-count="2"><button type="button" onClick="{{g.remove}}" aria-label="Remove tag {{g.label}}" style="height: 32px; padding: 0 10px 0 12px; display: inline-flex; align-items: center; gap: 6px; border: 0; border-radius: 999px; background: {{g.bg}}; color: {{g.fg}}; font: inherit; font-size: 13px; font-weight: 600; cursor: pointer;">{{g.label}}<span style="display: flex; opacity: .7;">${svg(I.close, 10, 2.4)}</span></button></sc-for><button type="button" onClick="{{${pk}.toggle}}" aria-expanded="{{${pk}.expanded}}" style="height: 32px; padding: 0 12px; display: inline-flex; align-items: center; gap: 6px; box-sizing: border-box; border: 1.5px dashed {{t.muted}}; border-radius: 999px; background: transparent; color: {{t.muted}}; font: inherit; font-size: 13px; font-weight: 600; cursor: pointer;">${svg(I.plus, 12, 2.4)}Add tag</button>${phone
  ? `<sc-if value="{{${pk}.open}}" hint-placeholder-val="{{ false }}"><div role="dialog" aria-label="Tags" style="position: absolute; inset: 0; z-index: 30; box-sizing: border-box; padding: 16px 20px 34px; border-radius: 32px 32px 0 0; background: {{t.bg}}; display: flex; flex-direction: column; gap: 12px;"><div style="display: flex; align-items: center; justify-content: space-between;"><span style="font-size: 18px; font-weight: 600;">Tags<span style="margin-left: 8px; font-family: ${MONO}; font-size: 13px; font-weight: 500; color: {{t.muted}};">{{${pk}.count}}</span></span><button type="button" onClick="{{${pk}.close}}" style="height: 36px; padding: 0 16px; border: 0; border-radius: 999px; background: {{t.inv}}; color: {{t.invText}}; font: inherit; font-size: 14px; font-weight: 600; cursor: pointer;">Done</button></div>${tagSearch(pk + '.query', pk + '.setQuery', 'Find or make a tag', 44)}<div style="flex-grow: 1; min-height: 0; overflow-y: auto; scrollbar-width: none; display: flex; flex-direction: column;">${makeRow(pk, 48)}<sc-for list="{{${pk}.options}}" as="o" hint-placeholder-count="8">${tagRow('o', { h: 48, line: true })}</sc-for></div></div></sc-if>`
  : `<sc-if value="{{${pk}.open}}" hint-placeholder-val="{{ false }}"><div role="dialog" aria-label="Add a tag" data-sc-pop style="position: absolute; left: 0; ${up ? 'bottom' : 'top'}: calc(100% + 8px); z-index: 30; width: 320px; ${popBox}">${tagSearch(pk + '.query', pk + '.setQuery', 'Find or make a tag')}<div style="max-height: 190px; overflow-y: auto; scrollbar-width: thin; display: flex; flex-direction: column;">${makeRow(pk)}<sc-for list="{{${pk}.options}}" as="o" hint-placeholder-count="5">${tagRow('o')}</sc-for></div></div></sc-if>`}</div>`;
const viewBtn = (key, handler, label, icon) => `<button type="button" onClick="{{${handler}}}" aria-label="${label}" aria-pressed="{{${key}.pressed}}" style="width: 42px; height: 36px; border: 0; border-radius: 999px; background: {{${key}.bg}}; color: {{${key}.fg}}; box-shadow: {{${key}.sh}}; display: flex; align-items: center; justify-content: center; cursor: pointer;">${svg(I[icon], 16, 2)}</button>`;
// One glass chip per tag on a deck's gradient card (a chip in list view). Clicking one shows every deck with that tag,
// like the chips in the +N menu, instead of opening the deck.
const glassTag = k => `<sc-if value="{{d.${k}.show}}" hint-placeholder-val="{{ true }}"><button type="button" onClick="{{d.${k}.pick}}" title="Every deck tagged {{d.${k}.label}}" style="height: 26px; padding: 0 11px; display: inline-flex; align-items: center; border: 0; border-radius: 999px; background: {{d.glass}}; box-shadow: inset 0 0 0 1px {{d.glassLine}}; color: inherit; font: inherit; font-size: 12px; font-weight: 600; white-space: nowrap; text-shadow: none; cursor: pointer; pointer-events: auto;">{{d.${k}.label}}</button></sc-if>`;
const tagSlot = k => `<sc-if value="{{d.${k}.show}}" hint-placeholder-val="{{ true }}"><button type="button" onClick="{{d.${k}.pick}}" title="Every deck tagged {{d.${k}.label}}" style="height: 24px; padding: 0 10px; display: inline-flex; align-items: center; border: 0; border-radius: 999px; background: {{d.${k}.bg}}; color: {{d.${k}.fg}}; font: inherit; font-size: 12px; font-weight: 600; white-space: nowrap; cursor: pointer; pointer-events: auto;">{{d.${k}.label}}</button></sc-if>`;
// A deck's +N chip opens a menu with all of its tags; pick one to see every deck that has it.
const deckTagsPop = pos => `<sc-if value="{{d.tagsOpen}}" hint-placeholder-val="{{ false }}"><div role="dialog" aria-label="Tags on {{d.name}}" data-sc-pop style="position: absolute; ${pos} z-index: 20; pointer-events: auto; width: 320px; box-sizing: border-box; padding: 16px; border-radius: 24px; background: {{t.bg}}; color: {{t.text}}; box-shadow: 0 18px 48px rgba(0,0,0,.2), 0 0 0 1px {{t.line}}; display: flex; flex-direction: column; gap: 12px; text-shadow: none;">
  <div style="display: flex; align-items: center; justify-content: space-between;"><span style="font-size: 14px; font-weight: 600;">{{d.tagCount}}</span><button type="button" onClick="{{d.toggleTags}}" aria-label="Close" style="width: 28px; height: 28px; border: 0; border-radius: 14px; background: {{t.surf}}; color: {{t.text}}; display: flex; align-items: center; justify-content: center; cursor: pointer;">${svg(I.close, 10, 2.4)}</button></div>
  <div style="display: flex; flex-wrap: wrap; gap: 6px;"><sc-for list="{{d.allTags}}" as="g" hint-placeholder-count="6"><button type="button" onClick="{{g.pick}}" style="height: 28px; padding: 0 11px; display: inline-flex; align-items: center; border: 0; border-radius: 999px; background: {{g.bg}}; color: {{g.fg}}; font: inherit; font-size: 12px; font-weight: 600; white-space: nowrap; cursor: pointer;">{{g.label}}</button></sc-for></div>
  <a href="{{d.settingsHref}}" style="align-self: flex-start; font-size: 13px; font-weight: 600; color: {{t.muted}};">Edit tags</a>
</div></sc-if>`;
const moreTag = (bg, h) => `<sc-if value="{{d.more.show}}" hint-placeholder-val="{{ false }}"><button type="button" onClick="{{d.toggleTags}}" aria-expanded="{{d.expanded}}" aria-label="Show all {{d.tagCount}}" style="height: ${h}px; padding: 0 10px; flex-shrink: 0; display: inline-flex; align-items: center; border: 0; border-radius: 999px; ${bg} font: inherit; font-size: 12px; font-weight: 600; white-space: nowrap; text-shadow: none; cursor: pointer; pointer-events: auto;">{{d.more.label}}</button></sc-if>`;
// A card's tag as a small chip; `k` names the row's tag slot (c1, c2).
const cardTag = k => `<sc-if value="{{r.${k}.show}}" hint-placeholder-val="{{ true }}"><span style="height: 22px; padding: 0 9px; display: inline-flex; align-items: center; border-radius: 999px; background: {{r.${k}.bg}}; color: {{r.${k}.fg}}; font-size: 11px; font-weight: 600; white-space: nowrap;">{{r.${k}.label}}</span></sc-if>`;
// Cards show up to two tags; with more, the first one and a +N (hover it to read the rest).
const cardMore = `<sc-if value="{{r.cMore.show}}" hint-placeholder-val="{{ false }}"><span title="{{r.cMore.title}}" style="height: 22px; padding: 0 8px; flex-shrink: 0; display: inline-flex; align-items: center; border-radius: 999px; background: {{t.surf}}; color: {{t.muted}}; font-size: 11px; font-weight: 600; white-space: nowrap;">{{r.cMore.label}}</span></sc-if>`;
const CARD_TAGS_JS = `const cardSlot = (tags, i) => (tags && tags[i] ? { show: true, ...tagChip(tags[i]) } : { show: false, label: '', bg: 'transparent', fg: t.text });
  const cardFit = tags => { const fit = tagFit(tags, 2); return { c1: cardSlot(fit.vis, 0), c2: cardSlot(fit.vis, 1), cMore: { show: fit.more > 0, label: '+' + fit.more, title: (tags || []).slice(fit.vis.length).join(', ') } }; };`;
// ---------- Study network: shared pieces (profiles, shared decks, Discover, suggestions, History, news) ----------
// The owner's note: "GitHub + Instagram for study material". The rules are the canvas's "How sharing works" board:
// the cards are shared, your progress never is; every deck starts private; Study a deck as it is or Make a copy;
// anyone can suggest a change and the owner takes it or skips it; every change is a version in History.
// Data: db.net (web/net.js in the app, net-sample.mjs on the canvas) answers each page; while an answer is on its way
// it's undefined, and the page shows its loading look. db.act has the changes (study, copyDeck, star, follow, …).
// People: their photo, or their initial on their color (the six colors of your own picture in Settings).
const PERSON_COLORS = ['linear-gradient(135deg, #8C9AFC 0%, #4F60E6 100%)', 'linear-gradient(135deg, #FFC857 0%, #EE5A36 100%)', 'linear-gradient(135deg, #7EE0B0 0%, #1F8F5F 100%)',
  'linear-gradient(135deg, #F9A8D4 0%, #D6336C 100%)', 'linear-gradient(135deg, #7DE3F0 0%, #0E8A9E 100%)', 'linear-gradient(135deg, #C4A7FF 0%, #7C3AED 100%)'];
// For a board's logic: `person(p)`, `netDeck(d)` (a shared deck as a cover tile), `kfmt(n)` (1.3k), `ago(iso)`, and
// `goTo(url, board)`: the app's own address in the app, the board's file on the canvas (canvas links are boards).
const NET_JS = `const PC = ${JSON.stringify(PERSON_COLORS)};
  const goTo = (url, board) => (db.mock ? board + '.dc.html' : url || '/');
  const person = p => { p = p || {}; const nm = String(p.name || ''); return { name: nm, handle: p.handle || '', at: p.handle ? '@' + p.handle : '', href: goTo(p.handle ? '/@' + p.handle : '', 'WebProfile'),
    initial: ((nm.trim() || '?')[0]).toUpperCase(), bg: PC[p.color || 0] || PC[0], photo: p.avatar || '', hasPhoto: !!p.avatar, noPhoto: !p.avatar,
    teacher: p.verified === 'teacher', school: p.verified === 'school' || p.kind === 'school', verified: !!p.verified }; };
  const kfmt = n => { n = +n || 0; return n >= 10000 ? Math.round(n / 1000) + 'k' : n >= 1000 ? (Math.round(n / 100) / 10 + 'k').replace('.0k', 'k') : String(n); };
  const MONTHS3 = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  const ago = iso => { const t = Date.parse(iso || ''); if (!t) return ''; const m = Math.max(0, Math.round((Date.now() - t) / 60000));
    if (db.mock) { const d = new Date(t); return MONTHS3[d.getUTCMonth()] + ' ' + d.getUTCDate(); }
    if (m < 1) return 'Just now'; if (m < 60) return m + ' min ago'; const h = Math.round(m / 60); if (h < 24) return h + 'h ago'; const dd = Math.round(h / 24); if (dd === 1) return 'Yesterday'; if (dd < 7) return dd + ' days ago';
    const d = new Date(t); return MONTHS3[d.getMonth()] + ' ' + d.getDate(); };
  const netDeck = d => { d = d || {}; const cv = d.cover || {}, pal = this.gen((cv.seed || d.name || 'Lucida') + (cv.round ? ' #' + cv.round : ''), cv.style || 'mix'), photo = cv.image && cv.image !== 'mock' ? cv.image : '';
    const badge = d.checked ? 'Checked' : d.owner && (d.owner.kind === 'school' || d.owner.verified === 'school') ? 'Official · ' + d.owner.name : d.pinned ? 'Pinned' : '';
    const cardsLine = kfmt(d.cards) + (d.cards === 1 ? ' card' : ' cards');
    return { ...pal, id: d.id || '', name: d.name || '', href: goTo(d.url, 'WebPublicDeck'), stats: kfmt(d.stars) + '   ' + cardsLine, cardsLine, stars: kfmt(d.stars),
      owner: person(d.owner), photo, hasPhoto: !!photo, badge, hasBadge: !!badge, badgeShield: !!d.checked || (!!d.owner && d.owner.kind === 'school') }; };`;
// A shared deck as a cover tile: its gradient (or photo), a badge (Checked, Pinned, a school), its name, saves, and cards.
const NET_TILE = (k, h, name = 22) => `<a href="{{${k}.href}}" class="sc-lift" style="position: relative; display: block; height: ${h}px; border-radius: 20px; overflow: hidden; color: {{${k}.ink}}; background: {{${k}.base}};">${flowLayer(k)}${GRAIN_LAYER}
    <sc-if value="{{${k}.hasPhoto}}" hint-placeholder-val="{{ false }}"><img src="{{${k}.photo}}" alt="" style="position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover;"><span style="position: absolute; inset: 0; background: linear-gradient(180deg, rgba(0,0,0,0) 40%, rgba(0,0,0,.55) 100%);"></span></sc-if>
    <span style="position: absolute; inset: 0; box-sizing: border-box; padding: 16px 18px; display: flex; flex-direction: column; justify-content: space-between; text-shadow: {{${k}.shadow}};">
      <span style="display: flex; min-height: 24px;"><sc-if value="{{${k}.hasBadge}}" hint-placeholder-val="{{ false }}"><span style="height: 24px; padding: 0 9px; display: inline-flex; align-items: center; gap: 5px; border-radius: 999px; background: rgba(0,0,0,.28); color: #FFFFFF; font-size: 11px; font-weight: 600; text-shadow: none; backdrop-filter: blur(8px);"><sc-if value="{{${k}.badgeShield}}" hint-placeholder-val="{{ true }}">${svg(I.shield, 12, 2)}</sc-if>{{${k}.badge}}</span></sc-if></span>
      <span style="display: flex; flex-direction: column; gap: 4px; min-width: 0;"><span style="font-size: ${name}px; font-weight: 600; letter-spacing: -.02em; line-height: 1.1; overflow: hidden; text-overflow: ellipsis; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical;">{{${k}.name}}</span><span style="display: flex; align-items: center; gap: 5px; font-size: 12px; opacity: .88;">${svg(I.star, 12, 2)}<span>{{${k}.stars}}</span><span style="margin-left: 6px;">{{${k}.cardsLine}}</span></span></span>
    </span></a>`;
// A person's round picture: their photo, or their initial on their color.
const PERSON_AV = (k, size) => `<span style="position: relative; width: ${size}px; height: ${size}px; flex-shrink: 0; border-radius: ${size / 2}px; overflow: hidden; background: {{${k}.bg}}; color: #FFFFFF; display: inline-flex; align-items: center; justify-content: center; font-size: ${Math.round(size * 0.42)}px; font-weight: 600; line-height: 1;"><sc-if value="{{${k}.noPhoto}}" hint-placeholder-val="{{ true }}">{{${k}.initial}}</sc-if><sc-if value="{{${k}.hasPhoto}}" hint-placeholder-val="{{ false }}"><img src="{{${k}.photo}}" alt="" referrerpolicy="no-referrer" style="position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover;"></sc-if></span>`;
// The small check a verified teacher or school has next to their name.
const VERIFIED = k => `<sc-if value="{{${k}.verified}}" hint-placeholder-val="{{ false }}"><span title="Verified" style="display: inline-flex; color: #3E63DD; flex-shrink: 0;">${svg(I.shield, 14, 2.2)}</span></sc-if>`;
// Signed out, a public page has no sidebar: the logo, Discover, and Sign in across the top.
const NET_TOP = `<header style="height: 64px; flex-shrink: 0; box-sizing: border-box; padding: 0 48px; display: flex; align-items: center; gap: 16px; border-bottom: 1px solid {{t.line}};"><a href="{{homeHref}}" aria-label="Lucida">${logo()}</a><span style="flex-grow: 1;"></span><a href="WebDiscover.dc.html" style="height: 36px; padding: 0 14px; display: inline-flex; align-items: center; border-radius: 999px; font-size: 14px; font-weight: 600; color: {{t.muted}};">Discover</a>${pill('Sign in', { inv: true, href: '{{signInHref}}' })}</header>`;
// A page of the study network on the web: the sidebar when you're signed in, the top bar when you aren't. `inner` is
// the page's <main> content.
const netRoot = (active, inner, extra = '') => `<div style="position: relative; width: 1440px; height: 900px; box-sizing: border-box; display: flex; overflow: hidden; font-family: ${FONT}; background: {{t.bg}}; color: {{t.text}};">
<sc-if value="{{signedIn}}" hint-placeholder-val="{{ true }}">${sidebar(active)}</sc-if>
<div style="flex-grow: 1; min-width: 0; display: flex; flex-direction: column;">
  <sc-if value="{{signedOutView}}" hint-placeholder-val="{{ false }}">${NET_TOP}</sc-if>
  <main style="flex-grow: 1; min-height: 0; box-sizing: border-box; padding: 36px 48px; display: flex; flex-direction: column; gap: 24px; overflow-y: auto;">
${inner}
  </main>
</div>
${extra}
</div>`;
// What every network page's logic adds: signed in or out, and where the top bar's links go.
const NET_VALS = `grain: String(this.props.grain ?? 0.7), signedIn: !db.signedOut && !this.props.signedOut, signedOutView: !!db.signedOut || !!this.props.signedOut, homeHref: db.mock ? 'Landing.dc.html' : 'https://lucida.cards/', signInHref: db.mock ? 'WebSignIn.dc.html' : '/sign-in?next=' + encodeURIComponent(location.pathname),`;
// The loading look: soft gray blocks where the page's parts will be.
const NET_LOADING = (rows = 3) => `<sc-if value="{{loading}}" hint-placeholder-val="{{ false }}"><div aria-label="Loading" style="display: flex; flex-direction: column; gap: 16px;"><div style="width: 280px; height: 34px; border-radius: 12px; background: {{t.surf}};"></div>${Array.from({ length: rows }, () => '<div style="height: 120px; border-radius: 20px; background: {{t.surf}};"></div>').join('')}</div></sc-if>`;
// Not there (the owner stopped sharing it, or a mistyped address).
const NET_MISSING = `<sc-if value="{{missing}}" hint-placeholder-val="{{ false }}"><div style="padding: 64px 24px; border-radius: 24px; background: {{t.surf}}; display: flex; flex-direction: column; align-items: center; gap: 10px; text-align: center;"><span style="font-size: 20px; font-weight: 600;">{{missingTitle}}</span><span style="font-size: 14px; color: {{t.muted}};">{{missingLine}}</span><a href="{{discoverHref}}" style="margin-top: 6px; height: 36px; padding: 0 16px; display: inline-flex; align-items: center; border-radius: 999px; background: {{t.inv}}; color: {{t.invText}}; font-size: 14px; font-weight: 600;">Discover decks</a></div></sc-if>`;

// Windows over a page (a popup, a side panel, a sheet from the bottom), and Report: the classes use them, and so do the deck,
// profile, and Suggestions pages, which come before the Classes section, so they live here.
const closeX = handler => `<button type="button" onClick="{{${handler}}}" aria-label="Close" style="width: 36px; height: 36px; flex-shrink: 0; border: 0; border-radius: 18px; background: {{t.surf}}; color: {{t.text}}; display: flex; align-items: center; justify-content: center; cursor: pointer;">${svg(I.close, 14, 2.2)}</button>`;
const cField = (value, onChange, placeholder, label, { icon = '', mono = false, type = 'text', attrs = '' } = {}) => `<label style="display: flex; align-items: center; gap: 10px; height: 50px; flex-shrink: 0; padding: 0 16px; box-sizing: border-box; border-radius: 16px; background: {{t.surf}}; color: {{t.muted}};">${icon ? svg(I[icon], 18, 1.8) : ''}<input type="${type}" value="{{${value}}}" onChange="{{${onChange}}}" placeholder="${placeholder}" aria-label="${label}" autocomplete="off"${attrs} style="flex-grow: 1; min-width: 0; height: 100%; border: 0; outline: 0; background: transparent; font: inherit; font-size: 16px; color: {{t.text}};${mono ? ` font-family: ${MONO}; font-size: 20px; letter-spacing: .18em; text-transform: uppercase;` : ''}"></label>`;
const errLine = k => `<sc-if value="{{${k}.hasErr}}" hint-placeholder-val="{{ false }}"><span role="alert" style="font-size: 13px; line-height: 1.4; color: {{t.again}};">{{${k}.err}}</span></sc-if>`;
const twoBtns = (k, action) => `<div style="display: flex; gap: 10px; flex-shrink: 0;"><button type="button" onClick="{{${k}.close}}" data-key="escape" style="flex: 1 1 0; height: 48px; border: 0; border-radius: 999px; background: {{t.surf}}; color: {{t.text}}; font: inherit; font-size: 15px; font-weight: 600; cursor: pointer;">Cancel</button><button type="button" onClick="{{${k}.save}}" aria-disabled="{{${k}.off}}" style="flex: 1 1 0; height: 48px; border: 0; border-radius: 999px; background: {{${k}.bg}}; color: {{${k}.fg}}; font: inherit; font-size: 15px; font-weight: 600; cursor: pointer; transition: background-color .15s, color .15s;">${action}</button></div>`;
// Windows over a page: a centered popup (web), a small popup above the keyboard (iPhone), a side panel (web), and a
// sheet from the bottom (iPhone; `full` sheets reach near the top).
const cDialog = (k, body, w = 440) => `<sc-if value="{{${k}.show}}" hint-placeholder-val="{{ false }}"><div style="position: absolute; inset: 0; z-index: 80; display: flex; align-items: center; justify-content: center;">
  <div class="sc-fade" onClick="{{${k}.close}}" style="position: absolute; inset: 0; background: {{t.dim}};"></div>
  <div role="dialog" aria-modal="true" aria-label="{{${k}.title}}" class="sc-pop" style="position: relative; width: ${w}px; max-height: calc(100% - 48px); overflow-y: auto; box-sizing: border-box; padding: 28px; border-radius: 32px; background: {{t.bg}}; color: {{t.text}}; box-shadow: 0 24px 64px rgba(0,0,0,.24); display: flex; flex-direction: column; gap: 16px;">
    ${body}
  </div>
</div></sc-if>`;
const cSheet = (open, label, body, close, full = true) => `<sc-if value="{{${open}}}" hint-placeholder-val="{{ false }}">
  <div class="sc-scrim" onClick="{{${close}}}" style="position: absolute; inset: 0; z-index: 60; background: {{t.dim}};"></div>
  <div role="dialog" aria-label="${label}" class="sc-sheet" style="position: absolute; left: 0; right: 0; bottom: 0; z-index: 61; ${full ? 'top: 56px;' : 'max-height: calc(100% - 56px);'} box-sizing: border-box; padding: 20px 20px 34px; border-radius: 32px 32px 0 0; background: {{t.bg}}; display: flex; flex-direction: column; gap: 14px; overflow: hidden;">
    ${body}
  </div>
</sc-if>`;
// Reporting a deck, a person, or a suggestion: a reason, and a line (needed for Other). Pages that report something
// include REPORT_JS in their logic (it reads this.state, and `repDefault` for a board that shows it open) and this
// sheet in their markup (REPORT_SHEET), then call openReport('deck' | 'profile' | 'suggestion', id, name).
const REPORT_BODY = `<div style="display: flex; align-items: flex-start; justify-content: space-between; gap: 12px;"><span style="display: flex; flex-direction: column; gap: 4px; min-width: 0;"><span style="font-size: 22px; font-weight: 600; letter-spacing: -.02em;">{{rep.title}}</span><span style="font-size: 14px; color: {{t.muted}}; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">{{rep.what}}</span></span>${closeX('rep.close')}</div>
    <sc-if value="{{rep.asking}}" hint-placeholder-val="{{ true }}"><div style="display: flex; flex-direction: column; gap: 12px;">
      <div role="radiogroup" aria-label="Why" style="display: flex; flex-direction: column; gap: 6px;"><sc-for list="{{rep.reasons}}" as="o" hint-placeholder-count="4"><button type="button" role="radio" aria-checked="{{o.pressed}}" onClick="{{o.pick}}" style="height: 50px; flex-shrink: 0; padding: 0 16px; display: flex; align-items: center; gap: 12px; border: 0; border-radius: 16px; background: {{t.surf}}; box-shadow: {{o.ring}}; color: {{t.text}}; font: inherit; font-size: 15px; font-weight: 500; text-align: left; cursor: pointer;"><span style="width: 18px; height: 18px; flex-shrink: 0; box-sizing: border-box; border-radius: 9px; border: {{o.dot}};"></span><span>{{o.label}}</span></button></sc-for></div>
      ${cField('rep.note', 'rep.setNote', '{{rep.notePh}}', 'A line about it', { attrs: ' maxlength="280"' })}
      ${errLine('rep')}
      ${twoBtns('rep', 'Send')}
    </div></sc-if>
    <sc-if value="{{rep.sent}}" hint-placeholder-val="{{ false }}"><div style="display: flex; flex-direction: column; gap: 14px;"><div style="padding: 18px; border-radius: 20px; background: {{t.surf}}; display: flex; align-items: center; gap: 12px;"><span style="display: flex;">${svg(I.check, 20, 2.4)}</span><span style="font-size: 15px; font-weight: 600;">Thanks. We’ll take a look.</span></div><button type="button" onClick="{{rep.close}}" style="height: 48px; border: 0; border-radius: 999px; background: {{t.inv}}; color: {{t.invText}}; font: inherit; font-size: 15px; font-weight: 600; cursor: pointer;">Done</button></div></sc-if>`;
const REPORT_SHEET = phone => (phone ? cSheet('rep.show', 'Report', REPORT_BODY, 'rep.close', false) : cDialog('rep', REPORT_BODY, 460));
const REPORT_JS = `const REASONS = [['wrong', 'Wrong or harmful'], ['spam', 'Spam'], ['stolen', 'Someone else’s work'], ['other', 'Other']];
  const rep0 = 'rep' in this.state ? this.state.rep : (typeof repDefault === 'undefined' ? null : repDefault);
  const openReport = (kind, id, name) => this.setState({ rep: { kind, id, name }, repReason: '', repNote: '', repSent: false, repErr: '' });
  const repReason = this.state.repReason || '', repNote = this.state.repNote || '', repOk = !!repReason && (repReason !== 'other' || !!repNote.trim());
  const rep = { show: !!rep0, title: rep0 ? ({ deck: 'Report this deck', profile: 'Report this person', suggestion: 'Report this suggestion' })[rep0.kind] || 'Report' : '', what: rep0 ? rep0.name || '' : '',
    asking: !!rep0 && !this.state.repSent, sent: !!rep0 && !!this.state.repSent,
    reasons: REASONS.map(([id, label]) => { const on = id === repReason; return { label, pressed: on ? 'true' : 'false', ring: on ? '0 0 0 2px ' + t.text : 'none', dot: on ? '6px solid ' + t.text : '2px solid ' + t.muted, pick: () => this.setState({ repReason: id, repErr: '' }) }; }),
    note: repNote, setNote: e => this.setState({ repNote: e && e.target ? e.target.value : '' }), notePh: repReason === 'other' ? 'What’s wrong?' : 'A line about it (if you like)',
    err: this.state.repErr || '', hasErr: !!this.state.repErr, off: repOk ? 'false' : 'true', bg: repOk ? t.inv : t.surf2, fg: repOk ? t.invText : t.muted,
    close: () => this.setState({ rep: null, repSent: false, repErr: '' }),
    save: () => { if (!repOk || !rep0) return;
      // Signed out (a public page), sending a report signs in first.
      if (!db.act.report) { db.act.go('/sign-in?next=' + encodeURIComponent(location.pathname)); return; }
      Promise.resolve(db.act.report({ kind: rep0.kind, id: rep0.id, handle: rep0.kind === 'profile' ? rep0.id : undefined, reason: repReason, note: repNote.trim() })).then(() => this.setState({ repSent: true }), e => this.setState({ repErr: e.message })); } };`;
// A quiet text button, with no background: "Report", last among a page's small actions.
const QUIET_BTN = (label, handler, { h = 44, size = 15 } = {}) => `<button type="button" onClick="{{${handler}}}" class="sc-press" style="height: ${h}px; padding: 0 0 0 14px; flex-shrink: 0; border: 0; background: transparent; color: {{t.muted}}; font: inherit; font-size: ${size}px; font-weight: 500; white-space: nowrap; cursor: pointer;">${label}</button>`;

// ---------- Library (was Decks) ----------
// A theme (Pro) draws a deck's cover (its picture, words, chips, button, and shadow); a deck with its own photo keeps it.
// SKIN_COVER_JS gives a deck's holes, from S (the board's theme) and C (S.coverOf(deck)); SKIN_THUMB is a Library row's
// small cover.
const SKIN_COVER_JS = `const coverSkin = C => (C ? { plain: false, skin: true, art: C.art, base: C.base, ink: C.ink, glass: C.glass, glassLine: C.glassLine, shadow: 'none', titleCss: C.title, btnBg: C.btnBg, btnFg: C.btnFg, coverShadow: C.shadow, coverCls: 'sk-cover' }
    : { plain: true, skin: false, art: null, titleCss: '', btnBg: '#FFFFFF', btnFg: '#000000', coverShadow: 'none', coverCls: '' });`;
const SKIN_THUMB = `<sc-if value="{{d.skin}}" hint-placeholder-val="{{ false }}"><span ref="{{d.thumb}}" data-sc-own aria-hidden="true" style="position: relative; display: block; width: 100%; height: 100%;"></span></sc-if>`;
// The owner (V96): "rename decks to library", folders for decks, and every card in one place to filter by tags and
// difficulty. One board is the whole Library: your folders and decks, one folder's decks (prop `folder`), or all your
// cards (prop `mode`). The app gives each its own address: /library, /library/folder/<id>, /library/cards.
const LIST_COLS = 'display: grid; grid-template-columns: 44px minmax(0, 1.5fr) minmax(0, 1.3fr) 70px 80px 120px 164px; gap: 16px; align-items: center;';
const CARD_COLS = 'display: grid; grid-template-columns: 36px minmax(0, 1.5fr) minmax(0, 1fr) minmax(0, .9fr) 170px 80px 96px; gap: 16px; align-items: center;';
// Decks or All cards: two links, since each is its own page.
const libModes = (h, fs = 13, grow = false) => `<div role="group" aria-label="Show" style="display: flex; gap: 2px; padding: 4px; border-radius: 999px; background: {{t.surf}};"><sc-for list="{{modes}}" as="m" hint-placeholder-count="2"><a href="{{m.href}}" aria-current="{{m.current}}" style="height: ${h}px; padding: 0 16px; ${grow ? 'flex: 1 1 0; ' : ''}display: inline-flex; align-items: center; justify-content: center; border-radius: 999px; background: {{m.bg}}; color: {{m.fg}}; box-shadow: {{m.sh}}; font-size: ${fs}px; font-weight: 600; white-space: nowrap;">{{m.label}}</a></sc-for></div>`;
// A folder: its first decks' colors fanned like cards, its name, and how many decks and due cards are in it.
const folderTile = (h, w, pad = '18px 20px') => `<a href="{{f.href}}" data-sc-drop="folder:{{f.id}}" data-sc-look="tile" draggable="false" class="sc-lift" style="position: relative; height: ${h}px; box-sizing: border-box; padding: ${pad}; border-radius: 20px; background: {{t.surf}}; display: flex; flex-direction: column; justify-content: space-between; overflow: hidden;">
  <span aria-hidden="true" style="position: relative; height: ${Math.round(w * .68) + 8}px;"><sc-for list="{{f.swatches}}" as="w" hint-placeholder-count="3"><span style="position: absolute; left: {{w.x}}; top: {{w.y}}; width: ${w}px; height: ${Math.round(w * .68)}px; border-radius: 12px; overflow: hidden; background: {{w.base}}; transform: rotate({{w.r}}); box-shadow: 0 8px 18px -8px rgba(0,0,0,.4), 0 0 0 2px {{t.surf}};"><sc-if value="{{w.skin}}" hint-placeholder-val="{{ false }}"><span ref="{{w.art}}" data-sc-own aria-hidden="true" style="position: absolute; inset: 0;"></span></sc-if></span></sc-for><sc-if value="{{f.empty}}" hint-placeholder-val="{{ false }}"><span style="position: absolute; left: -2px; top: 2px; color: {{t.muted}};">${svg(I.folder, 44, 1.5)}</span></sc-if></span>
  <span style="display: flex; flex-direction: column; gap: 3px; min-width: 0;"><span style="font-size: 17px; font-weight: 600; letter-spacing: -.01em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">{{f.name}}</span><span style="font-size: 13px; color: {{t.muted}};">{{f.line}}</span></span>
</a>`;
// Naming a folder, in a popup over the dimmed page (the owner: "'new folder' button should bring up a popup menu"): a new
// one, or this one (Rename). Enter or the button saves; Escape, Cancel, or a click outside closes it. On the iPhone it
// sits above the keyboard, drawn on the canvas (the app has the phone's own).
const folderPopup = phone => `<sc-if value="{{naming.show}}" hint-placeholder-val="{{ false }}"><div style="position: absolute; inset: 0; z-index: 80;${phone ? '' : ' display: flex; align-items: center; justify-content: center;'}">
  <div class="sc-fade" onClick="{{naming.cancel}}" style="position: absolute; inset: 0; background: {{t.dim}};"></div>
  <div role="dialog" aria-modal="true" aria-label="{{naming.title}}" class="sc-pop" style="position: ${phone ? 'absolute; left: 16px; right: 16px; top: 20%; padding: 20px; border-radius: 28px;' : 'relative; width: 440px; padding: 28px; border-radius: 32px; box-shadow: 0 24px 64px rgba(0,0,0,.24);'} box-sizing: border-box; background: {{t.bg}}; color: {{t.text}}; display: flex; flex-direction: column; gap: 16px;">
    <div style="display: flex; flex-direction: column; gap: 4px;"><span style="font-size: ${phone ? 20 : 22}px; font-weight: 600; letter-spacing: -.02em;">{{naming.title}}</span><sc-if value="{{naming.hasHint}}" hint-placeholder-val="{{ true }}"><span style="font-size: 14px; line-height: 1.4; color: {{t.muted}};">{{naming.hint}}</span></sc-if></div>
    <label style="display: flex; align-items: center; gap: 10px; height: 50px; padding: 0 16px; box-sizing: border-box; border-radius: 16px; background: {{t.surf}}; color: {{t.muted}}; box-shadow: inset 0 0 0 2px {{t.text}};">${svg(I.folder, 18, 1.8)}<input type="text" value="{{naming.value}}" onChange="{{naming.set}}" onKeyDown="{{naming.key}}" ref="{{naming.ref}}" placeholder="Folder name" aria-label="Folder name" maxlength="80" autocomplete="off" style="flex-grow: 1; min-width: 0; height: 100%; border: 0; outline: 0; background: transparent; font: inherit; font-size: 16px; color: {{t.text}};"></label>
    <div style="display: flex; gap: 10px;"><button type="button" onClick="{{naming.cancel}}" data-key="escape" style="flex: 1 1 0; height: 48px; border: 0; border-radius: 999px; background: {{t.surf}}; color: {{t.text}}; font: inherit; font-size: 15px; font-weight: 600; cursor: pointer;">Cancel</button><button type="button" onClick="{{naming.save}}" aria-disabled="{{naming.off}}" style="flex: 1 1 0; height: 48px; border: 0; border-radius: 999px; background: {{naming.bg}}; color: {{naming.fg}}; font: inherit; font-size: 15px; font-weight: 600; cursor: pointer; transition: background-color .15s, color .15s;">{{naming.action}}</button></div>
  </div>${phone ? `
  <sc-if value="{{drawKb}}" hint-placeholder-val="{{ true }}">${KEYBOARD()}</sc-if>` : ''}
</div></sc-if>`;
// While a card is dragged: the Move to tray, your other decks to drop it on (see drag.mjs). `key` names the decks.
const moveTray = (key, phone) => `<div data-sc-tray="1" style="display: {{trayShow}}; position: absolute; ${phone ? 'left: 12px; right: 12px; bottom: 24px;' : 'left: 240px; right: 0; bottom: 28px; justify-content: center;'} z-index: 70; pointer-events: none;">
  <div role="group" aria-label="Move to" class="sc-tray" style="${phone ? 'flex-grow: 1; min-width: 0; padding: 14px 14px 16px; border-radius: 28px;' : 'max-width: 880px; padding: 14px 16px 16px; border-radius: 26px;'} box-sizing: border-box; background: {{t.bg}}; color: {{t.text}}; box-shadow: 0 0 0 1px {{t.line}}, 0 24px 64px rgba(0,0,0,.24); display: flex; flex-direction: column; gap: 10px; pointer-events: auto;">
    <span style="padding: 0 4px; font-size: 12px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; color: {{t.muted}};">Move to</span>
    <div style="display: flex; flex-wrap: wrap; gap: 8px; max-height: ${phone ? 184 : 136}px; overflow: hidden;"><sc-for list="{{${key}}}" as="o" hint-placeholder-count="4"><span data-sc-drop="deck:{{o.id}}" data-sc-look="chip" style="max-width: 100%; height: 40px; box-sizing: border-box; padding: 0 14px 0 8px; display: inline-flex; align-items: center; gap: 8px; border-radius: 999px; background: {{o.bg}}; color: {{o.fg}}; font-size: 14px; font-weight: 600; white-space: nowrap;"><span style="width: 24px; height: 24px; flex-shrink: 0; border-radius: 8px; background: {{o.base}};"></span><span style="min-width: 0; overflow: hidden; text-overflow: ellipsis;">{{o.name}}</span></span></sc-for></div>
  </div>
</div>`;
// Decks and cards you can drag (see drag.mjs): a held finger drags instead of selecting words or opening the phone's
// link menu. A deck's row lights up under the pointer, since all of it opens the deck. The popup and the Move to tray
// rise in; reduced motion keeps them still.
const DRAG_CSS = '.sc-drag{-webkit-touch-callout:none;-webkit-user-select:none;user-select:none}.sc-hit:focus-visible{outline:2px solid currentColor;outline-offset:-2px}'
  + '.sc-row .sc-hit::before{content:"";position:absolute;inset:4px -12px;border-radius:14px;background:currentColor;opacity:0;transition:opacity .15s}.sc-row:hover .sc-hit::before{opacity:.05}'
  + '@keyframes scTray{from{opacity:0;transform:translateY(18px) scale(.98)}}.sc-tray{animation:scTray .3s cubic-bezier(.2,.8,.2,1)}'
  + '@keyframes scPop{from{opacity:0;transform:translateY(12px) scale(.97)}}.sc-pop{animation:scPop .26s cubic-bezier(.2,.8,.2,1)}@keyframes scFade{from{opacity:0}}.sc-fade{animation:scFade .2s ease}'
  + '@media (prefers-reduced-motion:reduce){.sc-tray,.sc-pop,.sc-fade{animation:none}}';
// How a dragged deck or card looks while it's lifted: a tile gets a deeper shadow; a row gets the page behind it, a
// little room around its words, and a shadow.
const LIFT_JS = `const liftTile = 'border-radius:20px!important;box-shadow:0 30px 60px -18px rgba(0,0,0,.5)!important;';
  const liftRow = 'background:' + t.bg + '!important;border-radius:12px!important;border-bottom-color:transparent!important;box-shadow:0 0 0 12px ' + t.bg + ',0 0 0 13px ' + t.line + ',0 24px 48px -12px rgba(0,0,0,' + (this.props.dark ? '.8' : '.25') + ')!important;';
  const dragKey = this.dragKey || (this.dragKey = 'b' + Math.random().toString(36).slice(2, 8)), dragList = el => this.dragList(el);`;
// A deck's folder menu: into a folder, out of one, or into a new one.
const moveMenu = pos => `<sc-if value="{{d.moveOpen}}" hint-placeholder-val="{{ false }}"><div role="dialog" aria-label="Move {{d.name}}" data-sc-pop style="position: absolute; ${pos} z-index: 25; width: 240px; ${popBox} text-shadow: none;"><span style="padding: 8px 12px 4px; font-size: 12px; font-weight: 600; color: {{t.muted}};">Move to</span><sc-for list="{{d.moveTo}}" as="o" hint-placeholder-count="3"><button type="button" onClick="{{o.pick}}" aria-pressed="{{o.pressed}}" style="height: 38px; flex-shrink: 0; padding: 0 12px; display: flex; align-items: center; gap: 10px; border: 0; border-radius: 12px; background: transparent; color: {{t.text}}; font: inherit; font-size: 14px; text-align: left; cursor: pointer;"><span style="display: flex; color: {{t.muted}};">${svg(I.folder, 16, 1.8)}</span><span style="flex-grow: 1; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">{{o.label}}</span><sc-if value="{{o.on}}" hint-placeholder-val="{{ false }}"><span style="display: flex;">${svg(I.check, 14, 2.4)}</span></sc-if></button></sc-for><button type="button" onClick="{{d.newFolder}}" style="height: 38px; flex-shrink: 0; padding: 0 12px; display: flex; align-items: center; gap: 10px; border: 0; border-radius: 12px; background: {{t.surf}}; color: {{t.text}}; font: inherit; font-size: 14px; font-weight: 600; text-align: left; cursor: pointer;">${svg(I.plus, 13, 2.4)}New folder</button></div></sc-if>`;
const moveBtn = (bg, size = 32) => `<button type="button" onClick="{{d.toggleMove}}" aria-label="Move {{d.name}} to a folder" aria-expanded="{{d.moveExpanded}}" style="width: ${size}px; height: ${size}px; flex-shrink: 0; border: 0; border-radius: ${size / 2}px; ${bg} display: flex; align-items: center; justify-content: center; cursor: pointer; pointer-events: auto;">${svg(I.more, 16, 2)}</button>`;
// All cards: how hard each one is, as a colored dot and word.
const levelTag = `<span style="display: inline-flex; align-items: center; gap: 6px; font-size: 13px; font-weight: 600; color: {{r.levelFg}};"><span style="width: 8px; height: 8px; border-radius: 4px; background: {{r.levelFg}};"></span>{{r.level}}</span>`;
