    left: left.map(x => ({ label: x.label, ...look(doneIds.includes(x.id) ? 'done' : wrong && wrong[0] === x.id ? 'wrong' : sel === x.id ? 'sel' : 'idle'), pick: () => { if (!doneIds.includes(x.id)) pickL(x.id); } })),
